<?php require_once 'app.php'; require_admin();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$nome=post('nome');$email=filter_var(post('email'),FILTER_VALIDATE_EMAIL);$senha=(string)($_POST['senha']??'');$perfil=in_array(post('perfil'),['admin','usuario'],true)?post('perfil'):'usuario';if(!$nome||!$email||strlen($senha)<8)$err='Nome, e-mail válido e senha com 8 caracteres são obrigatórios.';else try{$s=db()->prepare('INSERT INTO usuarios(nome,email,senha,perfil) VALUES(?,?,?,?)');$s->execute([$nome,$email,password_hash($senha,PASSWORD_DEFAULT),$perfil]);flash('success','Usuário criado.');redirect('admin.php');}catch(PDOException $e){$err='E-mail já cadastrado.';}}layout_start('Novo usuário');?><div class="card p-4"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=csrf()?>"><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><div class="col-md-6"><label class="form-label">Nome</label><input name="nome" class="form-control" required></div><div class="col-md-6"><label class="form-label">E-mail</label><input type="email" name="email" class="form-control" required></div><div class="col-md-6"><label class="form-label">Senha inicial</label><input type="password" name="senha" minlength="8" class="form-control" required></div><div class="col-md-6"><label class="form-label">Perfil</label><select name="perfil" class="form-select"><option value="usuario">Usuário</option><option value="admin">Administrador</option></select></div><button class="btn btn-primary">Criar usuário</button></form></div><?php layout_end();